/**
 * frontmatter 契约门(共同派单契约 3 / 4 / 7):扫 `src/content/docs/**\/*.{md,mdx}`,逐文件核
 *   - 契约字段齐:title · description · zone · category · lastVerified
 *   - 枚举合法:zone ∈ {docs, support};category ∈ 11 类
 *   - lastVerified 形 YYYY-MM-DD(裸日期或带引号皆可)
 *   - related:形为站内 slug,且 slug 对应文章存在(当前语言或根语言)
 *   - sources:`contract/<path>` 须真存在于仓内 `contract/`;`tansr-cli:` / `tansr-api:` 只校形
 *   - 生成页:契约 4 列出的路径、或首行带 `<!-- generated by scripts/gen/… -->` 标记的文件,须 `generated: true`;
 *     反之 `generated: true` 的文件须带标记
 * 只用 node 内建模块;YAML 只解析本契约用到的子集(标量 / 字符串列表 / 行内数组),其余键原样跳过。
 *
 * 用法:node scripts/check/frontmatter.mjs [--root <dir>] [--json]
 *   退出码:0 全绿;1 有违反。
 * 自测卷:scripts/check/test/frontmatter.test.mjs(夹具在临时目录)。
 */
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, resolve } from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';
import {
  CATEGORY_VALUES,
  DATE_PATTERN,
  GENERATED_MARKER,
  GENERATED_PAGES,
  REQUIRED_FIELDS,
  SLUG_PATTERN,
  SOURCE_PATTERN,
  ZONE_VALUES,
} from '../../src/lib/contract.mjs';

export const DOCS_DIR = 'src/content/docs';

export const CODES = Object.freeze({
  NO_FRONTMATTER: 'no-frontmatter',
  MISSING: 'missing-field',
  BAD_ZONE: 'bad-zone',
  BAD_CATEGORY: 'bad-category',
  BAD_DATE: 'bad-last-verified',
  BAD_RELATED: 'bad-related-slug',
  RELATED_MISSING: 'related-not-found',
  BAD_SOURCE: 'bad-source-form',
  SOURCE_MISSING: 'source-not-found',
  GENERATED_FLAG: 'generated-flag-required',
  GENERATED_MARKER: 'generated-marker-required',
});

function parseArgs(argv) {
  const opts = { root: process.cwd(), json: false };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--root') opts.root = resolve(String(argv[++i] ?? '.'));
    else if (arg === '--json') opts.json = true;
    else throw new Error(`frontmatter: unknown argument ${arg}`);
  }
  return opts;
}

/** 去引号(单 / 双)并还原双引号转义 */
function unquote(raw) {
  const s = raw.trim();
  if (s.length >= 2 && s[0] === '"' && s[s.length - 1] === '"') return s.slice(1, -1).replace(/\\"/g, '"');
  if (s.length >= 2 && s[0] === "'" && s[s.length - 1] === "'") return s.slice(1, -1).replace(/''/g, "'");
  return s;
}

function scalar(raw) {
  const s = raw.trim();
  if (s === 'true') return true;
  if (s === 'false') return false;
  if (s.startsWith('[') && s.endsWith(']')) {
    const inner = s.slice(1, -1).trim();
    return inner === '' ? [] : inner.split(',').map((x) => unquote(x));
  }
  return unquote(s);
}

/**
 * 解析 frontmatter(`---` 围栏)为 { data, body }。
 * 支持:`key: 标量`、`key:` + 下方 `- 项` 列表、`key: [a, b]`;嵌套对象(如 hero:)整块跳过、键记为 object。
 */
export function parseFrontmatter(text) {
  const src = text.replace(/^\uFEFF/, '');
  const m = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/.exec(src);
  if (!m) return null;
  const lines = m[1].split(/\r?\n/);
  const data = {};
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line.trim() === '' || line.trim().startsWith('#')) {
      i += 1;
      continue;
    }
    const kv = /^([A-Za-z_][\w-]*):(?:\s+(.*))?$/.exec(line);
    if (!kv) {
      i += 1;
      continue;
    }
    const key = kv[1];
    const rest = (kv[2] ?? '').trim();
    if (rest !== '') {
      data[key] = scalar(rest);
      i += 1;
      continue;
    }
    // 块:列表或嵌套对象
    const block = [];
    i += 1;
    while (i < lines.length && (lines[i].trim() === '' || /^\s/.test(lines[i]))) {
      if (lines[i].trim() !== '') block.push(lines[i]);
      i += 1;
    }
    if (block.length > 0 && block.every((l) => /^\s*-\s/.test(l))) {
      data[key] = block.map((l) => unquote(l.replace(/^\s*-\s+/, '')));
    } else if (block.length === 0) {
      data[key] = null;
    } else {
      data[key] = { __object: true };
    }
  }
  return { data, body: src.slice(m[0].length) };
}

/** 列出 docs 下 md / mdx(相对 docs 目录,`/` 分隔) */
export function listDocs(root) {
  const base = join(root, DOCS_DIR);
  if (!existsSync(base)) return [];
  const out = [];
  const walk = (dir) => {
    for (const name of readdirSync(dir)) {
      const full = join(dir, name);
      const st = statSync(full);
      if (st.isDirectory()) walk(full);
      else if (/\.mdx?$/i.test(name)) out.push(relative(base, full).split('\\').join('/'));
    }
  };
  walk(base);
  return out.sort();
}

/** 文件相对路径 → 站内 slug(去扩展名;index → 目录;根 index → '') */
export function fileToSlug(file) {
  let s = file.replace(/\.mdx?$/i, '');
  if (s === 'index') return '';
  if (s.endsWith('/index')) s = s.slice(0, -'/index'.length);
  return s;
}

function localeOf(slug, extraLocales) {
  for (const l of extraLocales) if (slug === l || slug.startsWith(`${l}/`)) return l;
  return undefined;
}

export function checkFrontmatter({ root, extraLocales = ['en'] }) {
  const files = listDocs(root);
  const slugs = new Set(files.map(fileToSlug));
  const errors = [];
  const push = (file, code, detail) => errors.push({ file: `${DOCS_DIR}/${file}`, code, detail });
  for (const file of files) {
    const text = readFileSync(join(root, DOCS_DIR, file), 'utf8');
    const parsed = parseFrontmatter(text);
    if (!parsed) {
      push(file, CODES.NO_FRONTMATTER, 'file must start with a --- frontmatter block');
      continue;
    }
    const { data, body } = parsed;
    for (const f of REQUIRED_FIELDS) {
      if (data[f] === undefined || data[f] === null || data[f] === '') push(file, CODES.MISSING, f);
    }
    if (data.zone !== undefined && !ZONE_VALUES.includes(data.zone)) push(file, CODES.BAD_ZONE, String(data.zone));
    if (data.category !== undefined && !CATEGORY_VALUES.includes(data.category)) push(file, CODES.BAD_CATEGORY, String(data.category));
    if (data.lastVerified !== undefined && data.lastVerified !== null && !DATE_PATTERN.test(String(data.lastVerified))) {
      push(file, CODES.BAD_DATE, String(data.lastVerified));
    }
    const slug = fileToSlug(file);
    const locale = localeOf(slug, extraLocales);
    if (Array.isArray(data.related)) {
      for (const r of data.related) {
        if (!SLUG_PATTERN.test(r)) {
          push(file, CODES.BAD_RELATED, r);
          continue;
        }
        const inLocale = locale ? slugs.has(`${locale}/${r}`) : false;
        if (!inLocale && !slugs.has(r)) push(file, CODES.RELATED_MISSING, r);
      }
    }
    if (Array.isArray(data.sources)) {
      for (const s of data.sources) {
        if (!SOURCE_PATTERN.test(s)) {
          push(file, CODES.BAD_SOURCE, s);
          continue;
        }
        if (s.startsWith('contract/') && !existsSync(join(root, s))) push(file, CODES.SOURCE_MISSING, s);
      }
    }
    const firstBodyLine = body.split(/\r?\n/).find((l) => l.trim() !== '') ?? '';
    const hasMarker = GENERATED_MARKER.test(firstBodyLine.trim());
    const mustBeGenerated = hasMarker || GENERATED_PAGES.includes(file);
    if (mustBeGenerated && data.generated !== true) {
      push(file, CODES.GENERATED_FLAG, hasMarker ? 'has generated marker' : 'listed as generated page');
    }
    if (data.generated === true && !hasMarker) push(file, CODES.GENERATED_MARKER, 'generated: true but no <!-- generated by … --> marker on first body line');
  }
  return { summary: { files: files.length, errors: errors.length }, errors };
}

function main() {
  const opts = parseArgs(process.argv.slice(2));
  const result = checkFrontmatter(opts);
  for (const e of result.errors) console.error(`${e.file}: ${e.code}${e.detail ? ` (${e.detail})` : ''}`);
  if (opts.json) console.log(JSON.stringify(result));
  else console.log(`[frontmatter] ${JSON.stringify(result.summary)}`);
  process.exit(result.errors.length === 0 ? 0 : 1);
}

const invokedDirectly = process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) main();
